-- M1.7: phrases (SPEC F2/§5). Generated by drizzle-kit, then edited by hand before first use (see comments).
CREATE TABLE `phrases` (
	`id` text PRIMARY KEY NOT NULL,
	`word_id` text NOT NULL,
	`lang` text NOT NULL,
	`text` text NOT NULL,
	`reading` text NOT NULL,
	`gloss_vi` text NOT NULL,
	`gloss_en` text NOT NULL,
	`gloss_ko` text NOT NULL,
	`emoji` text,
	`audio_key` text,
	`ai_generated` integer DEFAULT false NOT NULL,
	`verified` integer DEFAULT false NOT NULL,
	`created_by_profile` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`word_id`) REFERENCES `words`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`created_by_profile`) REFERENCES `profiles`(`id`) ON UPDATE no action ON DELETE set null
);
--> statement-breakpoint
CREATE UNIQUE INDEX `phrases_lang_text_uq` ON `phrases` (`lang`,`text`);--> statement-breakpoint
CREATE INDEX `phrases_word_idx` ON `phrases` (`word_id`);--> statement-breakpoint
-- review_logs is rebuilt (card_id becomes nullable, ON DELETE SET NULL; new `lang`). No table references
-- review_logs, so dropping the old one deletes nothing else. D1 runs migrations in a transaction:
-- use defer_foreign_keys (PRAGMA foreign_keys has no effect there).
PRAGMA defer_foreign_keys = on;--> statement-breakpoint
CREATE TABLE `__new_review_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`card_id` text,
	`profile_id` text NOT NULL,
	`rating` integer NOT NULL,
	`reviewed_at` integer NOT NULL,
	`duration_ms` integer,
	`lang` text NOT NULL,
	`state` integer NOT NULL,
	`due` integer NOT NULL,
	`stability` real NOT NULL,
	`difficulty` real NOT NULL,
	`elapsed_days` integer NOT NULL,
	`last_elapsed_days` integer NOT NULL,
	`scheduled_days` integer NOT NULL,
	`learning_steps` integer NOT NULL,
	FOREIGN KEY (`card_id`) REFERENCES `cards`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`profile_id`) REFERENCES `profiles`(`id`) ON UPDATE no action ON DELETE cascade
);
