-- Backfill `lang` from the card's word (every existing log still has its card).
INSERT INTO `__new_review_logs`("id", "card_id", "profile_id", "rating", "reviewed_at", "duration_ms", "lang", "state", "due", "stability", "difficulty", "elapsed_days", "last_elapsed_days", "scheduled_days", "learning_steps")
  SELECT r."id", r."card_id", r."profile_id", r."rating", r."reviewed_at", r."duration_ms",
         (SELECT w."lang" FROM `cards` c JOIN `words` w ON w."id" = c."word_id" WHERE c."id" = r."card_id"),
         r."state", r."due", r."stability", r."difficulty", r."elapsed_days", r."last_elapsed_days", r."scheduled_days", r."learning_steps"
  FROM `review_logs` r;--> statement-breakpoint
DROP TABLE `review_logs`;--> statement-breakpoint
ALTER TABLE `__new_review_logs` RENAME TO `review_logs`;--> statement-breakpoint
