-- Hand-written triggers (not managed by drizzle-kit; tested in db/migrations.test.ts):
-- a row that belongs to a phrase must carry the phrase's root word in word_id,
-- and a phrase cannot be moved to another root word.
CREATE TRIGGER `examples_phrase_root_insert` BEFORE INSERT ON `examples`
WHEN NEW.`phrase_id` IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `phrases` p WHERE p.`id` = NEW.`phrase_id` AND p.`word_id` = NEW.`word_id`)
BEGIN
  SELECT RAISE(ABORT, 'examples.word_id must be the root word of examples.phrase_id');
END;--> statement-breakpoint
CREATE TRIGGER `examples_phrase_root_update` BEFORE UPDATE OF `word_id`, `phrase_id` ON `examples`
WHEN NEW.`phrase_id` IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `phrases` p WHERE p.`id` = NEW.`phrase_id` AND p.`word_id` = NEW.`word_id`)
BEGIN
  SELECT RAISE(ABORT, 'examples.word_id must be the root word of examples.phrase_id');
END;--> statement-breakpoint
CREATE TRIGGER `cards_phrase_root_insert` BEFORE INSERT ON `cards`
WHEN NEW.`phrase_id` IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `phrases` p WHERE p.`id` = NEW.`phrase_id` AND p.`word_id` = NEW.`word_id`)
BEGIN
  SELECT RAISE(ABORT, 'cards.word_id must be the root word of cards.phrase_id');
END;--> statement-breakpoint
CREATE TRIGGER `cards_phrase_root_update` BEFORE UPDATE OF `word_id`, `phrase_id` ON `cards`
WHEN NEW.`phrase_id` IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `phrases` p WHERE p.`id` = NEW.`phrase_id` AND p.`word_id` = NEW.`word_id`)
BEGIN
  SELECT RAISE(ABORT, 'cards.word_id must be the root word of cards.phrase_id');
END;--> statement-breakpoint
CREATE TRIGGER `phrases_root_fixed` BEFORE UPDATE OF `word_id` ON `phrases`
WHEN NEW.`word_id` <> OLD.`word_id`
BEGIN
  SELECT RAISE(ABORT, 'phrases.word_id (root word) cannot change');
END;
